NAME = 'CroSaric: Hrvatska Biblija Ivana Šarića'
BOOK = 'Baruch'

CHAPTERS = {
    1: {
        1: 'Ovo su riječi knjige koju u Babilonu napisa Baruh, sin Nerije, sina Maaseje, sina Sidkije, sina Hasadije, sina Hilkije,',
        2: 'pete godine, sedmoga dana u mjesecu, u vrijeme kada su Kaldejci osvojili Jeruzalem i spalili ga.',
        3: 'Baruh pročita riječi ove knjige pred Jekonijom, sinom Jojakimovim, kraljem Judinim, i pred čitavim narodom koji bijaše došao na čitanje knjige;',
        4: 'pred mogućnicima i kraljevim sinovima, pred starješinama, ukratko, pred svim narodom, malim i velikim, pred svima koji su živjeli u Babilonu, na obalama rijeke Suda.',
        5: 'Čuvši, plakali su, postili i molili se pred Gospodom.',
        6: 'Sabraše i novca, koliko tko mogaše,',
        7: 'i poslaše ga u Jeruzalem svećeniku Jojakimu, sinu Hilkije, Šalumova sina, i ostalim svećenicima i svemu narodu koji se s njim nalazio u Jeruzalemu.',
        8: 'Desetoga dana mjeseca Sivana Baruh je spasio posuđe kuće Gospodnje što bijaše ugrabljeno iz Hrama da bi ga odnio natrag u zemlju Judinu - srebrno posuđe što ga je načinio Sidkija, sin Jošijin, kralj Judin,',
        9: 'kad je Nabukodonozor, kralj babilonski, odveo iz Jeruzalema i u Babilon doveo Jekoniju s knezovima, ključarima, mogućnicima i svim narodom.',
        10: 'I napisaše: Evo, šaljemo vam novac da njime kupite žrtve paljenice i tamjan; pripravite žrtve i prinesite ih za grijehe na žrtveniku Gospoda, Boga našega.',
        11: 'I molite se za život Nabukodonozora, kralja babilonskog, i za život sina njegova Baltazara da im dani na zemlji budu kao dani neba;',
        12: 'neka nam Gospod dade snage i prosvijetli oči naše da bismo živjeli u sjeni Nabukodonozora, kralja babilonskog, i u sjeni njegova sina Baltazara, da bismo ih dugo služili te našli milost pred njima.',
        13: 'Molite se i za nas Gospodu, Bogu našem, jer smo ga uvrijedili i do danas se gnjev i srdžba Gospodnja nije odvratila od nas.',
        14: 'Čitajte, dakle, knjigu koju vam šaljemo i obznanite je u kući Gospodnjoj, na blagdan i u dane Zborovanja.',
        15: 'Recite tada: Pravedan je Gospod, Bog naš! Ali nama treba da se danas zacrvene od stida obrazi - nama Judejcima i žiteljima jeruzalemskim,',
        16: 'našim kraljevima i knezovima, našim svećenicima i prorocima i našim ocima,',
        17: 'jer smo griješili pred Gospodom, bili mu nepokorni',
        18: 'i nismo slušali glasa Gospoda, Boga svojega, da hodimo po zapovjedima koje Gospod bijaše stavio pred nas.',
        19: 'Od dana kada je oce naše izveo iz Egipta pa do dana današnjega nepokorni smo bili Gospodu, Bogu svojem, i nismo marili da čujemo njegov glas.',
        20: 'Tada navališe na nas nevolje i prokletstva kojima se Gospod zaprijetio sluzi svome Mojsiju u dan kada je izveo oce naše iz Egipta da bi nam dao zemlju kojom teče med i mlijeko. I tako je to do danas.',
        21: 'Nismo bili poslušali glas Gospoda, Boga svojega, ni riječi njegovih preko proroka koje nam je on slao;',
        22: 'svaki je od nas hodio po nagnuću svoga opakog srca, služeći drugim bogovima i čineći što nije po volji Gospodu, Bogu našem.',
    },
    2: {
        1: 'Zato je Gospod izvršio prijetnju koju je naviještao protiv nas, protiv naših sudaca koji su sudili Izraelu, protiv naših kraljeva i knezova, protiv naroda Izraelova i Judina:',
        2: 'pod čitavim nebom nije se još dogodilo ništa slično onome što se dogodilo u Jeruzalemu, prema onome što bijaše zapisano u Mojsijevu Zakonu -',
        3: 'da se jelo meso sina i kćeri.',
        4: 'Predao ih je vlasti svih kraljevstava oko nas, na porugu i prokletstvo među svim okolnim narodima kamo ih je raspršio Gospod.',
        5: 'Bijahu podjarmljeni umjesto da budu gospodari, jer - sagriješismo Gospodu, Bogu svojemu, ne poslušavši glasa njegova.',
        6: 'Da, pravedan je Gospod, Bog naš! Ali nama - nama treba da se danas zacrvene od stida obrazi, nama i ocima našim.',
        7: 'Oborila se na nas sva zla kojima nam Gospod bijaše zaprijetio.',
        8: 'Mi pak nismo umolili lice Gospodnje odvrativši se od misli svojih opakih srdaca.',
        9: 'Gospod tada uze bdjeti nad nevoljama koje je navalio na nas; jer pravedan je Gospod u svim djelima koja nam je naložio,',
        10: 'ali mi nismo slušali njegova glasa niti smo hodili po zapovijedima koje je Gospod pred nas stavio.',
        11: 'A sada, Gospode, Bože Izraelov, koji si snažnom rukom izveo narod svoj iz Egipta znamenjima i čudesima, velikom snagom i ispruženom desnicom, proslavivši tako ime svoje do dana današnjega:',
        12: 'mi smo sagriješili, bezbožni smo bili i nepravedni pred svim tvojim zapovijedima, Gospode, Bože naš!',
        13: 'Neka se odvrati gnjev tvoj od nas, jer smo samo malen ostatak među narodima kamo si nas raspršio.',
        14: 'Usliši, Gospode, molitvu našu i vapaj: izbavi nas poradi sebe i udijeli nam milost svoju, pred licem onih koji su nas u sužanjstvo odveli,',
        15: 'da sva zemlja zna da si ti Gospod, Bog naš, jer Izrael i njegov rod nosi tvoje ime.',
        16: 'Obazri se, Gospode, iz svetoga svoga prebivališta i svrni misao na nas, prikloni uho i poslušaj,',
        17: 'otvori oči i pogledaj: tÓa mrtvi u podzemnom svijetu - kojima je iz utrobe oduzet dah - ne, oni više ne kazuju slave i pravednosti Gospodnje;',
        18: 'samo duša ojađena, koja hodi pognuto i iznemoglo, ugaslih očiju, duša pregladnjela, Gospode, iskazuje tvoju slavu i pravednost!',
        19: 'O Gospode, Bože naš! Ne upravljamo svoje prošnje tvome licu zbog zasluga svojih otaca i svojih kraljeva;',
        20: 'nego jer si ti poslao na nas gnjev svoj i srdžbu svoju, kako si bio navijestio po prorocima, slugama svojim, ovim riječima:',
        21: '"Ovako govori Gospod: Prignite šiju i služite kralju babilonskom, da ostanete u zemlji koju sam dao ocima vašim.',
        22: 'Ne poslušate li nalog Gospodnji da služite kralju babilonskom,',
        23: 'učinit ću da iz gradova judejskih i s trgova jeruzalemskih nestane pjesme radosti i pjesme veselja, pjesme zaručnika i pjesme zaručnice, i sva će zemlja postati pustoš bez stanovnika."',
        24: 'Ali mi nismo poslušali glasa tvog da služimo kralju babilonskom, i ti si tada izvršio prijetnje koje si navijestio po prorocima, slugama svojim, da će kosti kraljeva naših i kosti naših otaca biti izbačene iz svog počivališta.',
        25: 'I doista, one bjehu izbačene na žegu dana i studen noći. I umiralo se u strašnim mukama od kuge, gladi i mača.',
        26: 'A od kuće koja nosi Ime tvoje učinio si ono što je ona danas, zbog zloće kuće Izraelove i kuće Judine.',
        27: 'Pa ipak, Gospode, Bože naš, postupio si s nama po svoj svojoj dobroti i prevelikoj blagosti,',
        28: 'kako si obećao po sluzi svome Mojsiju onoga dana kada si mu zapovjedio da napiše Zakon tvoj za sinove Izraela ovim riječima:',
        29: '"Ako ne poslušate glasa mog, ovo veliko i bezbrojno mnoštvo zacijelo će se smanjiti među narodima kamo ću ih raspršiti;',
        30: 'a znam, taj narod tvrde šije neće poslušati. Ali u zemlji svog sužanjstva oni će se opametiti',
        31: 'i spoznati da sam ja Gospod, Bog njihov. I dat ću im srce i uši da čuju.',
        32: 'Oni će me hvaliti u zemlji svog izgnanstva i spominjat će se moga imena; obratit će se, i smekšat će im se tvrda šija,',
        33: 'i odvratit će se od opakih svojih djela, jer sjetit će se sudbine otaca svojih kad su griješili Gospodu.',
        34: 'Tada ću ih dovesti natrag u zemlju koju sam obećao zaklevši se njihovim ocima Abrahamu, Izaku i Jakovu, da gospodare njome. I umnožit ću ih, i oni se više neće smanjivati.',
        35: 'I uspostavit ću s njima vječni Savez: ja ću biti njihov Bog, a oni će biti moj narod. I neću više izgoniti svog naroda Izraela iz zemlje koju sam im dao."',
    },
    3: {
        1: 'Svevladaru Gospode, Bože Izraelov, tebi viče duša tjeskobna, duh uznemiren:',
        2: 'Čuj, Gospode, i smiluj se jer smo sagriješili pred tobom.',
        3: 'Ti vladaš vječito, a mi propadamo bez prestanka.',
        4: 'Gospode svemogući, Bože Izraelov, čuj dakle molitvu samrtnika Izraelovih, sinova onih koji su protiv tebe sagriješili, koji nisu slušali glasa Gospoda, Boga svojega, pa zato navališe na nas nevolje.',
        5: 'Ne spominji se opačina naših otaca, već se spomeni u ovo vrijeme ruke svoje i Imena svoga.',
        6: 'Da, ti si Gospod, Bog naš, i mi te hoćemo slaviti, Gospode.',
        7: 'TÓa zato si nam u srce usadio strah svoj da bismo zazvali Ime tvoje i da bismo te proslavili u izgnanstvu uklonivši iz srca svu zloću naših otaca, koji su sagriješili pred tobom.',
        8: 'Evo nas još danas u ovom izgnanstvu kamo si nas raspršio na užas, prokletstvo i pokaranje zbog svih opačina naših.',
        9: 'Čuj, Izraele, životne propise, prisluhni da naučiš mudrost.',
        10: 'Zašto, o Izraele, zašto si u zemlji neprijatelja i zašto stariš u tuđini,',
        11: "onečišćujuć' se mrtvacima, ubrojen među one koji su u Podzemlju?",
        12: 'Zato što si Vrelo Mudrosti ostavio!',
        13: 'Da si Božjim hodio putem, zauvijek bi prebivao u miru.',
        14: 'Nauči stoga gdje je mudrost, gdje snaga, gdje li razboritost, pa da ujedno spoznaš u čemu je dugovječnost i život i gdje je svjetlost očinja i mir.',
        15: 'Ali tko je otkrio prebivalište Mudrosti, tko li prodro u njene riznice?',
        16: 'Gdje su vladari narodÄa, gdje gospodari zvijeri zemaljskih,',
        17: 'gdje oni koji se igrahu pticÄa nebeskih i oni koji zgrtahu srebro i zlato - u što se ljudi uzdaju - te ne bijaše kraja zgrtanju njihovu?',
        18: 'I gdje su oni koji s tolikim trudom srebro kovahu da im djela nitko natkriliti ne može?',
        19: 'Iščezli su, otišli u Podzemlje! Na njihovo mjesto dođoše drugi.',
        20: 'Mlađi ugledaše svjetlo dana, nastaniše zemlju, no puta Mudrosti ni oni ne otkriše;',
        21: 'staza njenih ni oni ne razumješe, ne doumiše joj se - sinovi njeni daleko ostadoše od puta njezina.',
        22: 'Nije se čulo o njoj u Kanaanu niti se vidjela u Temanu;',
        23: 'ni sinovi Hagarini što zemsku umnost ištu, ni trgovci iz Midjana i Teme, ni pjesnici priča, ni istraživači umnosti ne spoznaše puta Mudrosti, ne dovinuše se staza njezinih.',
        24: 'Kako je veliko, o Izraele, kako je veliko Božje prebivalište i kako je prostrano mjesto posjeda njegova?',
        25: 'Veliko i bezgranično, visoko - neizmjerno!',
        26: 'Ondje se rodiše divovi, čuveni od davnine, rastom golemi, vješti u boju;',
        27: 'ali njih ne izabra Bog niti im povjeri put spoznanja;',
        28: 'izginuše jer ne imaše mudrosti, izginuše sa svoje ludosti.',
        29: 'Tko se na nebo pope, pa da je dohvati - na oblake, pa da je skine?',
        30: 'Tko prebrodi more da bi je otkrio pa da je kupi za najčistije zlato?',
        31: 'Nitko ne zna njezina puta i nitko njezine staze ne shvaća.',
        32: 'Sveznajući - samo je on poznaje, svojim je umom proniče: on koji je za sva vremena sazdao zemlju i svu je životinjama naselio;',
        33: "on koji pošalje svjetlost, i ona, gle, pođe; natrag je zovne, i dršćuć' ona ga posluša.",
        34: 'Zvijezde mu veselo sjaju na svojim postajama;',
        35: 'zovne li ih, one mu odgovore: "Evo nas!" - i radosno sjaju svom Stvoritelju.',
        36: "On je naš Bog: nitko se drugi s njim usporedit' ne može.",
        37: 'On je pronikao sav put spoznaje i predao je sluzi svom Jakovu - Izraelu, svome ljubimcu.',
        38: 'Potom se ona na zemlji pojavila, među ljudima udomila.',
    },
    4: {
        1: 'Ona je knjiga Božjih zapovijedi, Zakon koji će trajati dovijeka: tko ga se držao bude, taj će živjeti; tko ga napusti, taj će umrijeti.',
        2: 'Vrati se, Jakove, i prihvati je, hodi k sjaju, k njenoj svjetlosti:',
        3: 'ne ustupaj slavu svoju drugomu, ni dostojanstvo svoje narodu tuđemu.',
        4: 'Blago nama, Izraele, jer nam je otkriveno što je Bogu po volji!',
        5: 'Ohrabri se, narode moj, spomene Izraelov!',
        6: 'Bili ste prodani narodima, ali ne na uništenje. Boga ste razgnjevili, stoga biste izručeni neprijateljima;',
        7: 'Stvoritelja svog ste izazvali žrtvujući zlodusima, a ne Bogu.',
        8: 'Zaboravili ste Boga vječnog, svoga hranioca! Ožalostili ste i Jeruzalem - majku koja vas je othranila.',
        9: 'Kada je vidjela gdje se na vas obara gnjev od Boga, stade naricati: "Slušajte, susjede sionske: u tugu veliku zavi me Gospod.',
        10: 'Vidjeh gdje mi u sužanjstvo izruči Vječni sinove i kćeri.',
        11: 'S radošću sam ih hranila, s tugom i plačem gledam gdje odlaze.',
        12: "Nitko nek' se nada mnom ne raduje što obudovjeh i ostadoh sama. Zbog grijeha djece svoje opustjeh, jer se okrenuše od Božjeg Zakona.",
        13: 'Nisu marili za njegove zapovijedi niti išli putovima njegovih propisa, niti stupali stazom stege u njegovoj pravednosti.',
        14: 'Dođite, susjede sionske! Gledajte gdje mi u sužanjstvo predaje Vječni sinove i kćeri!',
        15: 'Doveo je na njih narod iz daljine, narod drzak, tuđega jezika, bez poštovanja prema starcu, bez smilovanja prema djetetu;',
        16: 'odvedoše udovi ljubimce, ostaviše je samu, bez kćeri.',
        17: 'Kako bih vam mogla ja pomoći?',
        18: "Samo onaj koji dovede na vas ove nevolje izbavit' vas može iz ruku neprijatelja.",
        19: 'Idite, djeco, otiđite svojim putem! Ja ostajem napuštena, samotna;',
        20: 'skinuh haljinu mira, odjenuh se u kostrijet svojih vapaja: sve dane svoje zazivat ću Vječnoga.',
        21: 'Ohrabrite se, djeco, zavapite Bogu: on će vas izbaviti iz nasilja, iz ruku neprijatelja.',
        22: 'Jer u Vječnog se uzdam, on će vas spasiti; od Svetoga očekujem radost: uskoro na vas će se smilovati, Vječni, Spasitelj vaš.',
        23: 'S tugom i plačem vidjeh vas gdje odlazite, ali Bog će vas meni vratiti s radošću i klicanjem za sva vremena.',
        24: 'Kao što susjede sionske vidješe gdje vas zasužnjuju, tako će naskoro vidjeti gdje će vas izbaviti Bog, koji će doći u velikoj slavi i sjaju Vječnoga.',
        25: "Djeco moja, podnesite pokaranje što se obori na vas od Boga. Neprijatelj te progonio, al' uskoro vidjet ćeš njegovu propast, na njegovu ćeš šiju staviti nogu.",
        26: 'Moja su nježna djeca hodila grubim putovima, otjerana kao stado što ga ote neprijatelj.',
        27: 'Ohrabrite se, djeco, zavapite Bogu: Onaj koji vas stavi na kušnju, on će vas se spomenuti.',
        28: 'Ako vam je misao, zastranivši, bila daleko od Boga, vratite se i tražite ga revnošću deseterostrukom.',
        29: 'Jer onaj koji je na vas nesreću doveo, vašim će spasenjem vratiti vam vječnu radost.',
        30: 'Ohrabri se, Jeruzaleme, utješit će te onaj koji ti dade ime.',
        31: 'Jao onima koji te zlostavljaju, koji se vesele tvojoj propasti!',
        32: 'Jao gradovima kojima su tvoja djeca robovala, teško onom koji ti odvede sinove!',
        33: 'Jer kao što je uživao u tvojemu padu i tvojoj se propasti radovao, tako će tugovati nad svojim opustošenjem.',
        34: "Neće se veseliti mnogome pučanstvu, obijest će mu se preobratit' u tugovanje,",
        35: 'od Vječnoga na nj će doći oganj za mnogo dana, i za dugo vrijeme bit će stan zlodusima.',
        36: 'Obazri se na istok, Jeruzaleme, vidi radost što ti dolazi od Boga.',
        37: 'Evo, vraćaju ti se sinovi koje si vidio gdje odlaze, sabiru se u tebi od istoka do zapada na zapovijed Svetoga i kliču u slavu Božju.',
    },
    5: {
        1: 'Skini, Jeruzaleme, haljinu tugovanja i nesreće, odjeni se zauvijek ljepotom slave Božje,',
        2: 'ogrni se plaštem Božje pravednosti, stavi na glavu vijenac slave Vječnoga;',
        3: 'jer Bog hoće pokazati sjaj tvoj svemu pod nebom',
        4: "i zasvagda ti hoće dati ime: 'Mir pravednosti' i 'Slava bogoljubnosti'.",
        5: "Ustani, Jeruzaleme, stani na visoko i obazri se na istok: Pogledaj! Djeca se tvoja sabiru, od istoka do zapada, na zapovijed Svetoga, radujuć' se što ih se spomenuo Bog.",
        6: 'Otišli su od tebe pješice, vodio ih neprijatelj, a gle, Bog ih tebi vraća nošene u slavlju, kao djecu kraljevsku.',
        7: "I naredi Bog: neka se snize sve visoke gore i vječne klisure; nek' se doline ispune i poravna zemlja da Izrael čvrsto kroči u sjaju slave Božje.",
        8: 'A šume i sva stabla mirisna činit će sjenu Izraelu po Božjoj zapovijedi;',
        9: 'jer Bog će voditi Izraela u radosti, u svjetlu njegove slave, prateć\' ga milosrđem svojim i pravednošću."',
    },
    6: {
        1: 'Prijepis poslanice koju je poslao Jeremija sužnjima koje je kralj Babilonaca uskoro imao odvesti u Babilon da im saopći preporuke što mu ih je povjerio Bog. Zbog grijeha što ste ih pred Bogom počinili, Nabukodonozor, kralj Babilonaca, odvest će vas kao sužnje u Babilon.',
        2: 'Kada stignete u Babilon, ostat ćete ondje mnogo godina i za dugo vrijeme, do sedmog naraštaja, a potom ću vas odande u miru izvesti.',
        3: 'A u Babilonu vidjet ćete bogove - srebrne, zlatne i drvene - koji se nose na leđima i koji neznabošcima strah zadaju.',
        4: 'Čuvajte se! Ne povodite se za tuđim narodima i nemojte da vas pred tim bogovima strah obuzme',
        5: 'kad opazite pred njima i za njima mnoštvo koje im se klanja. Recite u srcu: "Tebi se, Gospode, jedinomu treba klanjati."',
        6: 'Jer s vama je moj anđeo - njemu ste životom svojim odgovorni.',
        7: 'Jezik im je izgladio umjetnik, drugi su ih obložili zlatom i srebrom: obmana su i govoriti ne mogu.',
        8: 'Kao za gizdavu djevojku, uzimaju zlato i prave krune za glave svojih bogova.',
        9: 'A dogodi se te svećenici potkradaju sa svojih bogova zlato i srebro i troše ga za sebe; daruju ga čak i bludnicama u bludilištima. Ukrašuju ih haljinama kao ljude -',
        10: 'te bogove, srebrne, zlatne i drvene, no oni se od hrđe i crvotoči obraniti ne mogu',
        11: 'usprkos grimizu kojim ih odijevaju. Potrebno im je čistiti lica od hramske prašine koja napada na njih.',
        12: 'Jedan drži žezlo kao poglavar pokrajine, ali nikog tko bi ga uvrijedio ne može pogubiti;',
        13: 'drugi u desnici drži mač i sjekiru, ali se ne može obraniti ni od rata ni od razbojnika.',
        14: 'Po tom jasno slijedi: to bogovi nisu - njih se, dakle, ne bojte!',
        15: 'Kao što posuda kojom se čovjek služi postaje beskorisnom kada se razbije, tako je i s njihovim bogovima koji su postavljeni u hramovima.',
        16: 'Oči su im pune prašine što je dižu noge onih koji ulaze.',
        17: 'I kao što su na sve strane zatvorena vrata onome koji se ogriješio o kralja te ima biti pogubljen, tako svećenici utvrđuju hramove ovih bogova vratima, bravama i zasunima, bojeći se da ih razbojnici ne opljačkaju.',
        18: 'Užižu im svjetiljke u mnogo većem broju negoli sebi samima, ali nijedne od njih bogovi ne mogu vidjeti.',
        19: 'Nalik su na grede hrama: srce im iznutra, kažu, crvi rastaču - crvi koji gmižu iz zemlje te rastaču njih i njihove haljine.',
        20: 'Oni i ne osjećaju da im je lice pocrnjelo od dima što se diže u hramu.',
        21: 'Na njihova tijela i glave dolijeću šišmiši, lastavice i druge ptice; a ima i mačaka.',
        22: 'Po tim ćete znacima prepoznati da to bogovi nisu - njih se, dakle, ne bojte!',
        23: 'Ne očiste li im naslagu sa zlata kojim su obloženi za ukras, sami ga neće osvjetlati. Nisu ni osjećali dok su ih salijevali.',
        24: 'Kupovali su ih za najvišu cijenu, a nema u njima životnoga daha.',
        25: 'Bez nogu su, pa ih na ramenima nose i tad pokazuju svoje ruglo ljudima; stide ih se i oni koji im služe,',
        26: 'jer padne li koji bog na zemlju, oni ga moraju podići; usprave li ih, oni se sami od sebe neće pomaći; ako se nagnu, ne mogu se uspraviti.',
        27: 'Kao mrtvacima darove im prinose. Svećenici im njihovi tada odnose žrtve da izvuku korist prodajući ih. Isto tako i njihove žene prigrabe po dio, ne dijeleći ništa siromasima i nemoćnima. Njihovih se žrtava dotiču žene u čišćenju, a i porodilje.',
        28: 'Po tom dobro znate: to bogovi nisu - ništa ih se ne bojte!',
        29: 'TÓa kako biste ih mogli zvati bogovima? Tima srebrnim, zlatnim i drvenim bogovima žrtve prinose žene.',
        30: 'U njihovim hramovima svećenici sjede poderanih haljina, obrijane glave i brade, ne pokrivajući glave;',
        31: 'tule i viču pred svojim bogovima, kao na mrtvačkim gozbama.',
        32: 'Svećenici im skidaju haljine te njima odijevaju svoje žene i djecu.',
        33: 'Učine li im kakvo dobro ili zlo, oni to ne mogu uzvratiti;',
        34: 'niti mogu koga učiniti kraljem ili ga svrgnuti; niti mogu dati bogatstvo ili novac. Učini li im tko zavjet pa ga ne održi, oni ga ne mogu prisiliti da za to odgovara.',
        35: 'Oni ne mogu čovjeka spasiti od smrti niti slabijeg osloboditi od jačeg;',
        36: 'ne mogu slijepcu vratiti vid niti izbaviti čovjeka iz nevolje;',
        37: 'ne mogu se smilovati udovici niti učiniti dobro siroti.',
        38: 'Nalik su na kamenje iz planine, ti bogovi obloženi zlatom i srebrom. Oni koji ih štuju stidjet će se!',
        39: 'Kako se, dakle, mogu smatrati ili nazivati bogovima!',
        40: 'I sami ih Kaldejci obeščašćuju; jer videći nijema čovjeka koji ne može govoriti, oni ga dovode Belu i traže da čovjek progovori, kao da bi ga bog mogao čuti;',
        41: 'i nesposobni su promisliti o tome i ostaviti te bogove, toliko su lišeni razbora!',
        42: 'Žene opasane užetom sjede na putovima i pale kad od maslinovih ljusaka;',
        43: 'kada koju od njih snubi prolaznik da mu se poda, ona se ruga svojoj susjedi što je nisu zapazili kao nju i što joj uže nije prekinuto.',
        44: 'Sve što se događa u blizini tih bogova prijevara je; kako ih, dakle, mogu smatrati ili nazivati bogovima!',
        45: 'Načiniše ih drvodjelje i zlatari, i nisu drugo doli tvorevina njihova.',
        46: 'Njihovi izrađivači ne žive dugo; kako bi njihove rukotvorine bile bogovi?',
        47: 'Jer svojim će potomcima ostaviti samo obmanu i sramotu.',
        48: 'Ako ljude pogodi rat ili nevolja, svećenici se među sobom savjetuju gdje da se s njima sakriju;',
        49: 'kako ne uvidjeti da to nisu bogovi kad ni sami sebe ne mogu izbaviti od rata i od nevolja?',
        50: 'Po svemu tomu znat će se: ti drveni idoli, obloženi zlatom ili srebrom, samo su prijevara! Svima, narodima i kraljevima, bit će jasno: nisu to bogovi, nego su djela ruku ljudskih: nikakva Božjeg udjela u njima nema!',
        51: 'Kome, dakle, neće biti jasno: to bogovi nisu?',
        52: 'TÓa ne mogu oni postaviti kralja u nekoj zemlji niti dati kišu ljudima;',
        53: 'ne mogu presuditi u svojim poslovima niti izbaviti potlačenog; nemoćni su oni poput vrana između neba i zemlje.',
        54: 'Neka padne vatra na hram tih drvenih bogova obloženih zlatom ili srebrom, njihovi će svećenici pobjeći i spasiti se, dok će oni ondje izgorjeti kao grede.',
        55: 'Oni se ne mogu opirati ni kralju ni neprijatelju.',
        56: 'Kako onda pomisliti ili povjerovati da su to bogovi?',
        57: 'Ti drveni bogovi obloženi srebrom i zlatom ne mogu se obraniti ni od kradljivaca ni od razbojnika: kako su ovi jači od njih, opljačkat će im zlato i srebro i otići s haljinama u koje su odjeveni; oni su nesposobni sebi samima pomoći.',
        58: 'Zato je bolje biti kralj koji dokazuje svoju hrabrost, ili u kući korisna posuda kojom se vlasnik služi nego lažni bogovi; bolja su i vrata u kući koja čuvaju ono što je u njoj nego lažni bogovi; i drveni stup u kakvoj palači bolji je nego lažni bogovi.',
        59: 'Sunce, mjesec i zvijezde, dok sjaju da izvrše službu, poslušni su.',
        60: 'Milina je vidjeti i munju kada sijevne. A vjetar donosi dah svoj zemlji,',
        61: 'i oblaci, kada im Gospod zapovjedi da oblete svu zemlju, odmah izvrše nalog Božji. Vatra, poslana odozgo da sažeže gore i šume, izvršava što joj je naloženo.',
        62: 'Sa svim ovim ti se bogovi ni ljepotom ni snagom usporediti ne mogu.',
        63: 'Zato se ne može misliti ni reći da su to bogovi, jer nisu sposobni kazniti niti učiniti dobra ljudima.',
        64: 'Kada, dakle, znate da to bogovi nisu, njih se ne bojte!',
        65: 'Oni ne mogu ni prokleti ni blagosloviti kraljeva;',
        66: 'niti mogu narodima pokazati znamenja na nebu; oni ne sjaju kao sunce niti svijetle kao mjesec.',
        67: 'Zvijeri su od njih bolje; pobjeći one mogu u skrovište i sebi pomoći.',
        68: 'Nikako nam, dakle, nije jasno da su to bogovi; stoga ih se ne bojte!',
        69: 'Kao ptičje strašilo u nečuvanu polju lubenica, takvi su njihovi drveni bogovi obloženi zlatom i srebrom.',
        70: 'Jednako su slični glogovu grmu u vrtu na koji sjeda svaka ptica ili mrtvacu bačenu u mrak - ti drveni bogovi obloženi zlatom i srebrom.',
        71: 'Po grimizu i crvenilu što na njima trune prepoznat ćete da to nisu bogovi. Napokon i sami budu izjedeni te postanu na sramotu zemlji.',
        72: 'Koliko je bolji pravednik koji nema kumirÄa; sramota je daleko od njega!',
    },
}
